<script setup>
import { computed,onMounted,ref } from 'vue'
import { api } from './api'
import ContactFieldsPanel from './ContactFieldsPanel.vue'
const emit=defineEmits(['open-chat']);const contacts=ref([]),selected=ref(null),query=ref(''),loading=ref(false),error=ref('')
const count=computed(()=>contacts.value.length)
function initials(c){return `${c.first_name?.[0]||''}${c.last_name?.[0]||''}`.toUpperCase()||'T'}
function date(v){if(!v)return'—';return new Intl.DateTimeFormat(undefined,{dateStyle:'medium',timeStyle:'short'}).format(new Date(v))}
async function load(){loading.value=true;error.value='';try{contacts.value=await api.telegramContacts(query.value.trim());if(selected.value){selected.value=contacts.value.find(c=>c.id===selected.value.id)||null}}catch(e){error.value=e.message}finally{loading.value=false}}
async function choose(c){try{selected.value=await api.telegramContact(c.id)}catch(e){error.value=e.message}}
function clear(){query.value='';load()}
onMounted(load)
</script>
<template><div class="contacts-wrap"><section class="contacts-card"><div class="toolbar"><div><p class="eyebrow">Directory</p><h2>Telegram contacts <span>{{count}}</span></h2></div><button class="refresh" @click="load">↻ Refresh</button></div><form class="search" @submit.prevent="load"><span>⌕</span><input v-model="query" placeholder="Search name or Telegram username…"><button v-if="query" type="button" @click="clear">×</button></form><p v-if="error" class="error">{{error}}</p><div v-if="loading" class="empty">Loading contacts…</div><div v-else-if="!contacts.length" class="empty"><b>No Telegram contacts found</b><span>Contacts are created automatically when someone messages one of your connected bots.</span></div><div v-else class="table"><div class="thead"><span>Contact</span><span>Telegram ID</span><span>Bot / chats</span><span>Last activity</span></div><button v-for="c in contacts" :key="c.id" class="trow" :class="{active:selected?.id===c.id}" @click="choose(c)"><span class="identity"><i>{{initials(c)}}</i><span><b>{{c.name}}</b><small>@{{c.username||'no_username'}}</small></span></span><code>{{c.telegram_user_id}}</code><span class="bots"><b>{{c.conversation_count}} conversation{{c.conversation_count===1?'':'s'}}</b><small>{{c.conversations.map(x=>'@'+(x.bot.username||x.bot.first_name)).join(', ')||'—'}}</small></span><time>{{date(c.last_message_at)}}</time></button></div></section>
<aside class="profile" :class="{blank:!selected}"><template v-if="selected"><div class="profile-head"><span class="avatar">{{initials(selected)}}</span><h2>{{selected.name}}</h2><a v-if="selected.username" :href="`https://t.me/${selected.username}`" target="_blank" rel="noopener">@{{selected.username}} ↗</a><span v-else>No public username</span></div><div class="details"><label>Telegram user ID<strong>{{selected.telegram_user_id}}</strong></label><label>Language<strong>{{selected.language_code||'Not supplied'}}</strong></label><label>Telegram account<strong>{{selected.is_bot?'Bot':'User'}}</strong></label><label>First seen<strong>{{date(selected.created_at)}}</strong></label><label>Last updated<strong>{{date(selected.updated_at)}}</strong></label></div><ContactFieldsPanel :contact="selected" channel="telegram" compact /><div class="conversation-block"><p class="eyebrow">Conversations</p><article v-for="c in selected.conversations" :key="c.id"><div><b>@{{c.bot.username||c.bot.first_name}}</b><small>{{c.status}} · {{date(c.last_message_at)}}</small></div><button @click="emit('open-chat',c.id)">Open chat →</button></article></div></template><template v-else><div class="blank-icon">T</div><h3>Contact profile</h3><p>Select a Telegram contact to see their channel identity, subscriber fields and conversations.</p></template></aside></div></template>
<style scoped>
.contacts-wrap{display:grid;grid-template-columns:minmax(0,1fr) 370px;gap:16px}.contacts-card,.profile{background:#fff;border:1px solid #dce5e1;border-radius:14px;box-shadow:0 3px 14px rgba(21,57,43,.04);overflow:hidden}.toolbar{display:flex;align-items:center;justify-content:space-between;padding:19px 20px 13px}.eyebrow{margin:0;color:#229ed9;font-size:9px;font-weight:900;letter-spacing:.09em;text-transform:uppercase}.toolbar h2{margin:3px 0 0;font-size:19px}.toolbar h2 span{display:inline-grid;place-items:center;min-width:22px;height:22px;margin-left:5px;border-radius:999px;background:#e7f5fb;color:#1788ba;font-size:10px}.refresh{border:1px solid #d5e0db;background:#fff;border-radius:8px;padding:8px 10px;font-weight:700;cursor:pointer}.search{margin:0 20px 16px;border:1px solid #d3dfda;border-radius:9px;display:flex;align-items:center;padding:0 10px}.search input{flex:1;border:0;outline:0;padding:10px;background:transparent}.search button{border:0;background:transparent;font-size:18px;color:#819189;cursor:pointer}.table{border-top:1px solid #e8eeeb}.thead,.trow{display:grid;grid-template-columns:minmax(220px,1.4fr) minmax(130px,.7fr) minmax(180px,1fr) minmax(140px,.8fr);gap:12px;align-items:center}.thead{padding:9px 16px;background:#f7faf9;color:#7c8d85;font-size:9px;font-weight:800;text-transform:uppercase}.trow{width:100%;border:0;border-top:1px solid #edf1ef;background:#fff;padding:13px 16px;text-align:left;cursor:pointer}.trow:hover,.trow.active{background:#f2f9f6}.identity{display:flex;align-items:center;gap:9px;min-width:0}.identity i,.avatar{display:grid;place-items:center;background:#dff3fc;color:#1688bc;font-style:normal;font-weight:900}.identity i{width:36px;height:36px;border-radius:50%;flex:0 0 auto}.identity b,.identity small,.bots b,.bots small{display:block}.identity small,.bots small{margin-top:2px;color:#229ed9;font-size:9px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.trow code{font-size:10px;color:#536a60}.bots b{font-size:10px}.trow time{font-size:10px;color:#72847c}.profile{padding:22px;align-self:start;max-height:calc(100vh - 170px);overflow:auto}.profile.blank{text-align:center;padding:70px 30px;color:#75877f}.blank-icon,.avatar{width:58px;height:58px;margin:0 auto;border-radius:17px;background:#229ed9;color:#fff;font-size:20px}.profile.blank h3{color:#173026}.profile-head{text-align:center;padding-bottom:18px;border-bottom:1px solid #e7eeea}.profile-head h2{margin:10px 0 3px}.profile-head a,.profile-head>span{font-size:11px;color:#229ed9;text-decoration:none}.details{padding:8px 0}.details label{display:flex;justify-content:space-between;gap:10px;padding:10px 0;border-bottom:1px solid #edf1ef;color:#7b8c84;font-size:10px}.details strong{color:#28453a;text-align:right}.profile :deep(.contact-section){margin-top:14px;background:#fbfdfc;border:1px solid #e2e9e5;border-radius:10px;padding:12px}.profile :deep(.section-title){display:flex;align-items:center;justify-content:space-between;margin-bottom:10px}.profile :deep(.section-title h3),.profile :deep(.section-title p){margin:0}.profile :deep(.section-title p){font-size:8px;color:#229ed9}.conversation-block{margin-top:14px}.conversation-block article{display:flex;align-items:center;justify-content:space-between;gap:8px;padding:10px 0;border-bottom:1px solid #edf1ef}.conversation-block b,.conversation-block small{display:block}.conversation-block small{margin-top:3px;color:#83948c;font-size:9px}.conversation-block button{border:0;background:#e6f5fb;color:#147fae;border-radius:7px;padding:7px 8px;font-size:9px;font-weight:800;cursor:pointer}.empty{padding:50px 20px;text-align:center;color:#7c8d85}.empty b,.empty span{display:block}.empty span{margin-top:5px;font-size:11px}.error{margin:0 20px 12px;padding:9px;background:#fff0f0;color:#982e2e;border-radius:7px}@media(max-width:1050px){.contacts-wrap{grid-template-columns:1fr}.profile{order:-1}.thead{display:none}.trow{grid-template-columns:1fr 1fr}.trow time{text-align:right}}@media(max-width:650px){.trow{grid-template-columns:1fr}.trow time{text-align:left}}
</style>